public class Main {
    enum Day { MON, TUE, WED, THU, FRI, SAT, SUN }

    public static void main(String[] args) {
        Day today = Day.SAT;
        System.out.println(today + " is ordinal " + today.ordinal());
        boolean weekend = today == Day.SAT || today == Day.SUN;
        System.out.println("Weekend: " + weekend);
        for (Day d : Day.values()) {
            if (d.ordinal() % 3 == 0) {
                System.out.print(d + " ");
            }
        }
        System.out.println();
    }
}
